import {copilotMemoryAppBuilder} from '../config/app-builder'
import {mainQuery} from '@github-ui/react-core/future/main-query'
import type {BillingEntityData, Memory} from '../types/memory'

const memoryRoutePath = '/:owner?/:name?/settings/copilot/memory'

export type MemoryPayload = {
  memories: Memory[]
  loadError?: unknown
  /** Whether the memory opt-out feature is enabled for this repo */
  memoryOptOutEnabled?: boolean
  /** Whether memory is currently disabled by the repo admin */
  memoryDisabled?: boolean
  /** Path to update the memory_disabled setting */
  updateMemoryDisabledPath?: string
  /** Billing entity that will be charged for new memories created by the signed-in user */
  activeBillingEntity?: BillingEntityData | null
}

export const indexRoute = copilotMemoryAppBuilder.createQueryRouteConfig('indexRoute', {
  path: memoryRoutePath,
  queries: [mainQuery<MemoryPayload>()],
  index: true,
})

export const deleteRoute = copilotMemoryAppBuilder.createQueryRouteConfig('deleteRoute', {
  path: memoryRoutePath,
})
