import {registerDataRouterApp} from '@github-ui/react-core/register-app'
import {copilotMemoryAppBuilder} from './config/app-builder'
import {indexRoute, deleteRoute} from './routes/memory-route'
import {Memory} from './components/memory'

export const copilotMemoryApp = copilotMemoryAppBuilder.createDataRouterAppFromRoutes([
  indexRoute.toRoute({Component: Memory}),
  deleteRoute.toRoute({Component: Memory}),
])

registerDataRouterApp(copilotMemoryApp)
