import {ListView} from '@github-ui/list-view'
import {ListViewMetadata} from '@github-ui/list-view/ListViewMetadata'
import {ListItem} from '@github-ui/list-view/ListItem'
import {ListItemTitle} from '@github-ui/list-view/ListItemTitle'
import {ListItemDescription} from '@github-ui/list-view/ListItemDescription'
import {ListItemMainContent} from '@github-ui/list-view/ListItemMainContent'
import {ListItemActionBar} from '@github-ui/list-view/ListItemActionBar'
import {ActionList, Button, Banner, Link} from '@primer/react'
import {ControlGroup} from '@github-ui/control-group'
import {CommentAiIcon, GlobeIcon, OrganizationIcon, TrashIcon} from '@primer/octicons-react'
import type {BillingEntity, BillingEntityData, Memory} from '../types/memory'
import {indexRoute, deleteRoute} from '../routes/memory-route'
import type {MemoryPayload} from '../routes/memory-route'
import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {useRouteParams} from '@github-ui/react-core/future/use-route-params'
import {reactFetch} from '@github-ui/verified-fetch'
import type React from 'react'
import {useState} from 'react'
import {useMutation, useQueryClient} from '@github-ui/react-query'
import {Blankslate} from '@primer/react/experimental'
import {MemoryOptOutSettings} from './MemoryOptOutSettings'

const SourceAgents = {
  ccr: 'Copilot Code Review',
  cca: 'Copilot cloud agent',
}

function getSourceAgentName(agent: string): string {
  return SourceAgents[agent as keyof typeof SourceAgents] ?? agent
}

interface DeleteResult {
  deletedIds: string[]
  notDeletedIds: string[]
}

const EMPTY_STATE_DESCRIPTION = 'No memories are available or you may not have access to manage them.'
const LOAD_ERROR_DESCRIPTION = 'Copilot memory could not be loaded. Please try again later.'
const MEMORY_DISABLED_HEADING = 'Copilot memory is turned off'
const MEMORY_DISABLED_DESCRIPTION_CAN_ENABLE =
  'Copilot memory is turned off for this scope. Turn it on to start storing and retrieving memories.'
const MEMORY_DISABLED_DESCRIPTION_MANAGED =
  'Copilot memory is turned off for this scope. If this seems unexpected, contact your administrator.'

async function deleteMemories(path: string, ids: string[]): Promise<DeleteResult> {
  const data = new FormData()
  for (const id of ids) {
    data.append('ids[]', id)
  }
  const response = await reactFetch(path, {
    method: 'delete',
    body: data,
  })

  // 204 No Content means all deletions succeeded
  if (response.status === 204) {
    return {deletedIds: ids, notDeletedIds: []}
  }

  // 200 OK with body means partial success
  if (response.ok) {
    const body = await response.json()
    return {
      deletedIds: body.deleted_ids ?? [],
      notDeletedIds: body.not_deleted_ids ?? [],
    }
  }

  // Any other non-ok response is a complete failure
  throw new Error(`Failed to delete memory: ${response.statusText}`)
}

type MemoryListItemProps = {
  memory: Memory
  onDelete: (id: string) => void
  isSelected: boolean
  onSelect: (isSelected: boolean) => void
}

function getMostSpecificBillingEntity(
  billingEntityData: BillingEntityData,
): {entity: BillingEntity; isOrganization: boolean} | null {
  if (billingEntityData.organization) {
    return {entity: billingEntityData.organization, isOrganization: true}
  }
  if (billingEntityData.enterprise) {
    return {entity: billingEntityData.enterprise, isOrganization: false}
  }
  return null
}

function ActiveBillingEntityNotice({activeBillingEntityData}: {activeBillingEntityData: BillingEntityData | null}) {
  const activeBillingEntity = activeBillingEntityData ? getMostSpecificBillingEntity(activeBillingEntityData) : null

  if (activeBillingEntity) {
    const {entity, isOrganization} = activeBillingEntity
    const EntityIcon = isOrganization ? OrganizationIcon : GlobeIcon
    const entityLabel = (
      <span className="d-inline-flex flex-items-center gap-1 v-align-middle">
        <EntityIcon />
        <span className="text-bold">{entity.display_name}</span>
      </span>
    )

    return (
      <div className="mt-3" data-testid="active-billing-entity-notice">
        <p className="mb-1">Active billing entity: {entityLabel}</p>
        <p className="fgColor-muted mb-0">
          Only repository facts and user preferences associated with {entityLabel} will be available in agent runs.{' '}
          <Link href={entity.manage_billing_url} inline>
            Manage billing
          </Link>
          .
        </p>
      </div>
    )
  }

  return (
    <Banner
      variant="warning"
      title="No billing entity selected"
      description={
        <>
          Storage of repository facts and user preferences will fail if no billing entity is selected.{' '}
          <Link href="/settings/billing" inline>
            Manage billing
          </Link>
          .
        </>
      }
    />
  )
}

function MemoryListItem({memory, onDelete, isSelected, onSelect}: MemoryListItemProps) {
  const handleDelete = (e: React.MouseEvent | React.KeyboardEvent) => {
    e.preventDefault()
    onDelete(memory.id)
  }

  const memoryBillingEntity = memory.billing_entity ? getMostSpecificBillingEntity(memory.billing_entity) : null
  const MemoryBillingEntityIcon = memoryBillingEntity?.isOrganization ? OrganizationIcon : GlobeIcon

  return (
    <ListItem
      isSelected={isSelected}
      onSelect={onSelect}
      title={<ListItemTitle headingStyle={{minWidth: 0}} value={memory.fact} />}
      secondaryActions={
        <ListItemActionBar
          label="memory actions"
          actions={[
            {
              key: 'delete-memory',
              render: isOverflowMenu => {
                return isOverflowMenu ? (
                  <ActionList.Item onSelect={handleDelete}>
                    <ActionList.LeadingVisual>
                      <Button variant="invisible" size="small" aria-label="Delete memory" onClick={handleDelete}>
                        <TrashIcon />
                      </Button>
                    </ActionList.LeadingVisual>
                    Delete memory
                  </ActionList.Item>
                ) : (
                  <Button variant="invisible" size="small" aria-label="Delete memory" onClick={handleDelete}>
                    <TrashIcon />
                  </Button>
                )
              },
            },
          ]}
        />
      }
    >
      <ListItemMainContent>
        <ListItemDescription>
          <span className="color-fg-muted">{memory.subject}</span>
          {memory.source?.agent && (
            <span className="color-fg-muted ml-2">{getSourceAgentName(memory.source.agent)}</span>
          )}
          {memory.source?.baseModel && <span className="color-fg-muted ml-2">{memory.source.baseModel}</span>}
          {memoryBillingEntity && (
            <span className="color-fg-muted ml-2 d-inline-flex flex-items-center gap-1 v-align-middle">
              <MemoryBillingEntityIcon />
              <span>{memoryBillingEntity.entity.display_name}</span>
            </span>
          )}
        </ListItemDescription>
      </ListItemMainContent>
    </ListItem>
  )
}

export function Memory() {
  const payload = useRouteQuery(indexRoute, 'mainQuery')
  const {
    memories = [],
    loadError,
    memoryOptOutEnabled = false,
    memoryDisabled = false,
    updateMemoryDisabledPath,
    activeBillingEntity = null,
  }: MemoryPayload = payload?.data ?? {memories: []}
  const {owner, name} = useRouteParams(indexRoute)
  const isRepoPage = Boolean(owner && name)
  const deletePath = deleteRoute.generatePath({owner: owner ?? '', name: name ?? ''})

  // We want to update the index route payload after deletion(s).
  // Since the route is not mounted we will construct a partial query key.
  // See https://thehub.github.com/epd/engineering/dev-practicals/frontend/react/data-router/recipes/mutations/

  // Full query key for the current page's data — used to refetch the exact query backing this view.
  const currentPageQueryKey = payload.queryKey

  // Partial (prefix) query key for the index route — invalidates all cached variants
  // of the memories list (e.g. different pagination params) so stale data isn't shown
  // when navigating back.
  const indexRoutePartialQueryKey = indexRoute.queries.mainQuery.makeQueryKey()

  const queryClient = useQueryClient()
  const [deleteResult, setDeleteResult] = useState<DeleteResult | null>(null)

  const deleteMemoryMutation = useMutation({
    mutationFn: (ids: string[]) => deleteMemories(deletePath, ids),
    onSuccess: (result: DeleteResult) => {
      // Track partial success for UI feedback
      if (result.notDeletedIds.length > 0) {
        setDeleteResult(result)
      } else {
        setDeleteResult(null)
      }
      // Invalidate the index route query to refetch the updated list of memories
      queryClient.invalidateQueries({queryKey: currentPageQueryKey})
      queryClient.invalidateQueries({queryKey: indexRoutePartialQueryKey})
    },
    onError: () => {
      // Clear any previous partial success result on full failure
      setDeleteResult(null)
    },
  })

  const handleDeleteMemory = (id: string) => {
    setDeleteResult(null)
    deleteMemoryMutation.mutate([id])
  }
  const [selectedIds, setSelectedIds] = useState<Set<string>>(() => new Set())

  // `showMemoryDisabledState` is only used in the empty-state branch today, so
  // `memories.length === 0` is currently redundant. We keep it explicit to
  // document that the disabled copy is intended for an empty list only, in case
  // this flag is reused outside the current render branch in the future.
  const canChangeMemoryDisabledSetting = memoryOptOutEnabled && Boolean(updateMemoryDisabledPath)
  const showMemoryDisabledState = memoryDisabled && memories.length === 0

  const handleItemSelect = (id: string) => (selected: boolean) => {
    setSelectedIds(prev => {
      const next = new Set(prev)
      if (selected) next.add(id)
      else next.delete(id)
      return next
    })
  }

  const handleToggleSelectAll = (isAllSelected: boolean) => {
    if (isAllSelected) {
      setSelectedIds(new Set(memories.map(m => m.id)))
    } else {
      setSelectedIds(new Set())
    }
  }

  const handleDeleteMemories = async () => {
    if (selectedIds.size === 0) return
    setDeleteResult(null)
    const ids = Array.from(selectedIds)
    const result = await deleteMemoryMutation.mutateAsync(ids)
    // Only clear successfully deleted items from selection
    if (result.deletedIds.length > 0) {
      setSelectedIds(prev => {
        const next = new Set(prev)
        for (const id of result.deletedIds) {
          next.delete(id)
        }
        return next
      })
    }
  }

  return (
    <div>
      {/* Page header */}
      <div className="pb-3 mb-4">
        <h2 className="f2 text-normal mb-2">Copilot memory</h2>
        <p>
          Members can use{' '}
          <Link href="https://docs.github.com/copilot/concepts/agents/copilot-memory" inline>
            Copilot Memory
          </Link>{' '}
          to store facts about repositories and personal preferences about how they want to interact with Copilot. These
          are available to agents in future sessions. Users can turn this off at any time, regardless of enterprise or
          organization policy. Learn more in the{' '}
          <Link href="https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement" inline>
            Privacy Statement
          </Link>
          . This preview is governed by{' '}
          <Link href="https://docs.github.com/en/site-policy/github-terms/github-pre-release-license-terms" inline>
            GitHub&apos;s pre-release terms
          </Link>
          .
        </p>

        {memoryOptOutEnabled && updateMemoryDisabledPath && (
          <div className="mt-3">
            <h3 className="sr-only">General settings</h3>
            <ControlGroup>
              <MemoryOptOutSettings endpoint={updateMemoryDisabledPath} initialDisabled={memoryDisabled} />
            </ControlGroup>
          </div>
        )}

        {/* Active billing entity notice — user-scoped page only */}
        {!isRepoPage && <ActiveBillingEntityNotice activeBillingEntityData={activeBillingEntity} />}
      </div>

      {/* Memories list section */}
      <div>
        <h3 className="sr-only">Repository memories</h3>
        {deleteMemoryMutation.isError && (
          <Banner
            variant="critical"
            title="Error"
            hideTitle
            description="Failed to delete memories. Please try again."
          />
        )}
        {deleteResult && deleteResult.notDeletedIds.length > 0 && (
          <Banner
            variant="warning"
            title="Partial deletion"
            hideTitle
            description={`Successfully deleted ${deleteResult.deletedIds.length} ${deleteResult.deletedIds.length === 1 ? 'memory' : 'memories'}, but ${deleteResult.notDeletedIds.length} ${deleteResult.notDeletedIds.length === 1 ? 'memory' : 'memories'} could not be deleted.`}
            onDismiss={() => setDeleteResult(null)}
          />
        )}
        <ListView
          title="List of memories"
          isSelectable
          className="border rounded-2"
          metadata={
            memories.length > 0 ? (
              <ListViewMetadata
                title={`${memories.length} ${memories.length === 1 ? 'memory' : 'memories'}`}
                onToggleSelectAll={handleToggleSelectAll}
              >
                {selectedIds.size > 0 && (
                  <Button
                    leadingVisual={TrashIcon}
                    variant="danger"
                    onClick={handleDeleteMemories}
                    aria-label="Delete selected memories"
                  >
                    Delete
                  </Button>
                )}
              </ListViewMetadata>
            ) : undefined
          }
          totalCount={memories.length}
        >
          {memories.length > 0 ? (
            memories.map(m => (
              <MemoryListItem
                key={m.id}
                memory={m}
                onDelete={handleDeleteMemory}
                isSelected={selectedIds.has(m.id)}
                onSelect={handleItemSelect(m.id)}
              />
            ))
          ) : (
            <Blankslate>
              <Blankslate.Visual>
                <CommentAiIcon size="medium" />
              </Blankslate.Visual>
              <Blankslate.Heading>
                {showMemoryDisabledState
                  ? MEMORY_DISABLED_HEADING
                  : loadError
                    ? 'Unable to load memories'
                    : 'No memories found'}
              </Blankslate.Heading>
              <Blankslate.Description>
                {showMemoryDisabledState
                  ? canChangeMemoryDisabledSetting
                    ? MEMORY_DISABLED_DESCRIPTION_CAN_ENABLE
                    : MEMORY_DISABLED_DESCRIPTION_MANAGED
                  : loadError
                    ? LOAD_ERROR_DESCRIPTION
                    : EMPTY_STATE_DESCRIPTION}
              </Blankslate.Description>
            </Blankslate>
          )}
        </ListView>
      </div>
    </div>
  )
}
